use verus::prelude::*;

pub fn is_lowercase(c: char) -> bool {
    'a' <= c && c <= 'z'
}

pub fn is_uppercase(c: char) -> bool {
    'A' <= c && c <= 'Z'
}

pub fn to_uppercase(c: char) -> char {
    // c is assumed to be lowercase a-z
    // ASCII uppercase letter is 32 less than lowercase
    (c as u8 - 32) as char
}

pub fn to_lowercase(c: char) -> char {
    // c is assumed to be uppercase A-Z
    // ASCII lowercase letter is 32 more than uppercase
    (c as u8 + 32) as char
}

